// Extract PDF buffer from multipart form
const body = $input.item.json.body;
const fileBuffer = Buffer.from(body, 'base64');
return [{json: {file: fileBuffer, filename: $input.item.json.filename}}];

// Score candidate against job description
const resume = JSON.parse($input.item.json.content);
const jd = $('Set JD').item.json.job_description || '';

const techKeywords = ['Python', 'JavaScript', 'React', 'Node.js', 'PostgreSQL', 'AWS', 'Docker', 'Kubernetes'];
const matched = resume.skills.filter(s => jd.includes(s));
const techScore = Math.round((matched.length / Math.max(techKeywords.filter(k => jd.includes(k)).length, 1)) * 100);
const expScore = resume.experience_years >= 3 ? 90 : resume.experience_years >= 1 ? 70 : 50;
const overall = Math.round(techScore * 0.6 + expScore * 0.4);

return [{json: {...resume, overall_score: overall, tech_score: techScore, matched_skills: matched, recommendation: overall >= 80 ? 'Strong Hire' : overall >= 60 ? 'Consider' : 'Pass'}}];
